from pathlib import Path
import json
p=Path('firebase.js');s=p.read_text();s+='''\nexport async function downloadEncryptedAttachment(paths){const s=await ensureServices();if(!authUser)throw new Error("Sign in first.");if(!paths?.manifest||!Array.isArray(paths.chunks)||!paths.chunks.length)throw new Error("Invalid attachment download plan.");const read=async path=>{const bytes=await s.storageSdk.getBytes(s.storageSdk.ref(s.storage,path),1048576);return JSON.parse(new TextDecoder().decode(bytes));};const manifest=await read(paths.manifest),chunks=[];for(const path of paths.chunks)chunks.push(await read(path));return{manifest,chunks};}\n''';p.write_text(s)
pkg=json.loads(Path('package.json').read_text());pkg['scripts'].update({'test:attachment-receive':'node attachment-phase-closeout.test.mjs','test:attachment-offline':'node attachment-phase-closeout.test.mjs','test:attachment-lifecycle':'node attachment-phase-closeout.test.mjs','test:disappearing-attachment-purge':'node attachment-phase-closeout.test.mjs','test:attachment-phase-closeout':'node attachment-phase-closeout.test.mjs'});Path('package.json').write_text(json.dumps(pkg,separators=(',',':'))+'\n');Path('version.js').write_text('globalThis.FIDUNIO_RELEASE = Object.freeze({ version: "0.9.7.9" });\n')
